def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []
    arity = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        # Small chunks also support amounts beyond Python's int-string limit.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if (
            verb not in arity
            or len(parts) != arity[verb]
            or any(not token for token in parts)
        ):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue
            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        name = parts[1]

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        if verb == "open":
            if name in accounts:
                rejected.append(index)
                continue
            changes = ((name, None),)
            accounts[name] = (amount, False)

        elif verb == "deposit":
            if name not in accounts:
                rejected.append(index)
                continue
            balance, frozen = accounts[name]
            changes = ((name, accounts[name]),)
            accounts[name] = (balance + amount, frozen)

        elif verb == "withdraw":
            if name not in accounts:
                rejected.append(index)
                continue
            balance, frozen = accounts[name]
            if frozen or balance < amount:
                rejected.append(index)
                continue
            changes = ((name, accounts[name]),)
            accounts[name] = (balance - amount, frozen)

        elif verb == "transfer":
            destination = parts[2]
            if (
                name == destination
                or name not in accounts
                or destination not in accounts
            ):
                rejected.append(index)
                continue
            balance, frozen = accounts[name]
            if frozen or balance < amount:
                rejected.append(index)
                continue
            target_balance, target_frozen = accounts[destination]
            changes = (
                (name, accounts[name]),
                (destination, accounts[destination]),
            )
            accounts[name] = (balance - amount, frozen)
            accounts[destination] = (target_balance + amount, target_frozen)

        else:
            if name not in accounts:
                rejected.append(index)
                continue
            balance, frozen = accounts[name]
            desired_frozen = verb == "freeze"
            if frozen == desired_frozen:
                rejected.append(index)
                continue
            changes = ((name, accounts[name]),)
            accounts[name] = (balance, desired_frozen)

        history.append(changes)

    return {name: state[0] for name, state in accounts.items()}, rejected
